def _column_order(grid):
    rows = list(range(1, len(grid), 2))
    slots = (1, 4, 7, 10, 13)
    cols = [[int(bool(grid[r][c])) for r in rows] for c in slots]
    # Sort by increasing population; equal-population columns are ordered by
    # their top-to-bottom bit pattern, descending (as in the demonstrated tie).
    return sorted(range(5), key=lambda j: (sum(cols[j]), tuple(-x for x in cols[j])))


def transform(grid):
    out = [row[:] for row in grid]
    rows = list(range(1, len(grid), 2))
    slots = (1, 4, 7, 10, 13)
    order = _column_order(grid)
    for r in rows:
        old = [grid[r][c] for c in slots]
        for dest, source in enumerate(order):
            out[r][slots[dest]] = old[source]
    return out
